SELECT r.* FROM edu_homework_record r
JOIN edu_homework h ON h.id = r.homework_id AND h.deleted = 0
WHERE r.deleted = 0 AND h.teacher_id = #{teacherId}



            AND r.status IN (1, 2, 3, 4)
            AND r.status IN (1, 4)
            AND r.status = #{req.status}



        AND r.student_id = #{req.studentId}
        AND r.status = #{req.status}



    ORDER BY r.status ASC, r.submit_time ASC, r.id ASC
    ORDER BY r.id DESC
